/* Fallback letter avatar for concept skills */
const LetterIcon = ({ label, color }) => (
  <div className="skill-letter-icon" style={{ '--icon-color': color }} aria-hidden="true">
    {label.slice(0, 2).toUpperCase()}
  </div>
);

/* Map category → accent colour for visual variety */
const CATEGORY_META = {
  Programming:  { color: '#f7df1e', label: 'Programming Languages' },
  Frontend:     { color: '#61dafb', label: 'Frontend' },
  Backend:      { color: '#68d391', label: 'Backend' },
  Databases:    { color: '#fc8181', label: 'Databases' },
  Tools:        { color: '#b794f4', label: 'Tools & Version Control' },
  Concepts:     { color: '#f6ad55', label: 'Computer Science' },
};

/* Concept skill icon colours */
const CONCEPT_COLORS = {
  'REST APIs': '#4299e1',
  'Data Structures & Algorithms': '#68d391',
  'Object‑Oriented Programming': '#ed8936',
};

const containerVariants = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.1 } },
};
const cardVariants = {
  hidden: { opacity: 0, y: 20 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.45, ease: 'easeOut' } },
};

const Skills = () => {
  const [activeCategory, setActiveCategory] = useState('All');
  const categories = ['All', ...Object.keys(skills)];

  const filteredSkills =
    activeCategory === 'All'
      ? skills
      : { [activeCategory]: skills[activeCategory] };

  return (
    <section id="skills" className="skills-section" aria-label="Skills">
      <div className="container skills-wrapper">

        {/* Section header */}
        <motion.div
          className="skills-header"
          initial={{ opacity: 0, y: 24 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.6, ease: 'easeOut' }}
        >
          <span className="skills-label">Expertise</span>
          <h2 className="skills-title">Technical Skills</h2>
          <p className="skills-subtitle">
            Technologies I use to build complete, full-stack products.
          </p>
        </motion.div>

        {/* Category filter pills */}
        <motion.div
          className="skills-filter"
          role="tablist"
          aria-label="Filter skills by category"
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.5, delay: 0.15, ease: 'easeOut' }}
        >
          {categories.map((cat) => (
            <button
              key={cat}
              role="tab"
              aria-selected={activeCategory === cat}
              className={`skills-filter-btn${activeCategory === cat ? ' active' : ''}`}
              onClick={() => setActiveCategory(cat)}
            >
              {cat === 'All' ? 'All' : (CATEGORY_META[cat]?.label ?? cat)}
            </button>
          ))}
        </motion.div>

        {/* Skill category groups */}
        <AnimatePresence mode="wait">
          <div className="skills-groups" key={activeCategory}>
            {Object.entries(filteredSkills).map(([category, items]) => {
              const meta = CATEGORY_META[category] ?? { color: '#a0aec0', label: category };
              return (
                <div key={category} className="skills-group">
                  {/* Category heading */}
                  <motion.div
                    className="skills-group-header"
                    initial={{ opacity: 0, x: -16 }}
                    whileInView={{ opacity: 1, x: 0 }}
                    viewport={{ once: true, amount: 0.3 }}
                    transition={{ duration: 0.4, ease: 'easeOut' }}
                  >
                    <span
                      className="skills-group-dot"
                      style={{ background: meta.color }}
                      aria-hidden="true"
                    />
                    <h3 className="skills-group-title">{meta.label}</h3>
                  </motion.div>

                  {/* Skill cards */}
                  <motion.div
                    className="skills-grid"
                    variants={containerVariants}
                    initial="hidden"
                    whileInView="visible"
                    viewport={{ once: true, amount: 0.1 }}
                  >
                    {items.map((skill) => {
                      const icon = ICONS[skill];
                      const conceptColor = CONCEPT_COLORS[skill] ?? meta.color;
                      return (
                        <motion.div
                          key={skill}
                          className="skill-card card"
                          variants={cardVariants}
                          whileHover={{ y: -5, transition: { duration: 0.2 } }}
                          style={{ '--accent': meta.color }}
                          role="listitem"
                          aria-label={skill}
                        >
                          <div className="skill-card-icon">
                            {icon ?? (
                              <LetterIcon label={skill} color={conceptColor} />
                            )}
                          </div>
                          <span className="skill-card-name">{skill}</span>
                        </motion.div>
                      );
                    })}
                  </motion.div>
                </div>
              );
            })}
          </div>
        </AnimatePresence>

      </div>
    </section>
  );
};

export default Skills;
